import assert from "node:assert/strict";
import { add } from "./calculator.js";
const cases = [
  ["positive", 2, 3, 5],
  ["positive-float", 0.1, 0.2, 0.1 + 0.2],
  ["negative", -2, -3, -5],
  ["mixed", -7, 4, -3],
  ["zero-zero", 0, 0, 0],
  ["zero-right", 5, 0, 5],
  ["zero-left", 0, -5, -5],
];
let fails = 0;
for (const [name, a, b, expected] of cases) {
  let actual, status;
  try { assert.equal(add(a, b), expected); actual = add(a, b); status = "PASS"; }
  catch (e) { actual = add(a, b); status = "FAIL"; fails++; }
  console.log(`${status}\t${name}\tadd(${a}, ${b}) => ${actual}\texpected ${expected}`);
}
console.log(`total=${cases.length} failures=${fails}`);
console.log("typeof add(1,2) =", typeof add(1, 2));
process.exit(fails === 0 ? 0 : 1);
